import SwiftUI

// The digid wordmark for the start screen and the "Powered by digid" line (the same artwork as
// the digid SDKs' flows): the letters take the text colour, the mark keeps the brand ube #7379FD.

/// The wordmark, drawn in a 78 x 31 box scaled to the frame you give it.
struct DigidWordmark: View {
    var letters: Color = FlowColors.text

    var body: some View {
        ZStack {
            WordmarkShape(part: .letters).fill(letters)
            WordmarkShape(part: .mark).fill(Color(argb: 0xFF7379FD))
        }
        .aspectRatio(78.0 / 31.0, contentMode: .fit)
        .accessibilityHidden(true)
    }
}

private struct WordmarkShape: Shape {
    enum Part { case letters, mark }
    let part: Part

    func path(in rect: CGRect) -> Path {
        // The artwork's own coordinates, moved into the 78 x 31 box.
        let inBox: CGAffineTransform = part == .letters
            ? CGAffineTransform(translationX: 624.94 - 708.19, y: 414.76 - 554.88).scaledBy(x: 0.457, y: 0.457)
            : CGAffineTransform(translationX: 2 - 708.19, y: -554.88)
        let toRect = inBox.concatenating(CGAffineTransform(scaleX: rect.width / 78, y: rect.height / 31))
            .concatenating(CGAffineTransform(translationX: rect.minX, y: rect.minY))
        var path = Path()
        for d in part == .letters ? Self.letterPaths : Self.markPaths {
            path.addPath(Self.parse(d), transform: toRect)
        }
        return path
    }

    /// A minimal SVG path reader for the commands the artwork uses: absolute M, L, C and Z.
    private static func parse(_ d: String) -> Path {
        var path = Path()
        var numbers: [CGFloat] = []
        var command: Character = "M"
        func flush() {
            var n = numbers[...]
            func point() -> CGPoint? {
                guard n.count >= 2 else { return nil }
                defer { n = n.dropFirst(2) }
                return CGPoint(x: n[n.startIndex], y: n[n.startIndex + 1])
            }
            switch command {
            case "M":
                if let p = point() { path.move(to: p) }
                while let p = point() { path.addLine(to: p) }
            case "L":
                while let p = point() { path.addLine(to: p) }
            case "C":
                while n.count >= 6, let c1 = point(), let c2 = point(), let p = point() {
                    path.addCurve(to: p, control1: c1, control2: c2)
                }
            default:
                break
            }
            numbers.removeAll()
        }
        var token = ""
        func endToken() {
            if let v = Double(token) { numbers.append(CGFloat(v)) }
            token = ""
        }
        for ch in d {
            if ch.isLetter {
                endToken()
                flush()
                if ch == "Z" || ch == "z" { path.closeSubpath() }
                command = ch
            } else if ch == "," || ch == " " {
                endToken()
            } else if ch == "-" && !token.isEmpty {
                endToken()
                token = "-"
            } else {
                token.append(ch)
            }
        }
        endToken()
        flush()
        return path
    }

